import json,collections
c=collections.Counter()
for l in open('Condition.ndjson'):
    d=json.loads(l)
    for cc in d['code']['coding']:
        t=(cc.get('display') or '')
        if any(k in t.lower() for k in ['fibrillat','flutter']):
            c[(cc['code'],t)]+=1
for k,v in c.most_common(): print(v,k)
"

